
Action: create_file({"file_text":"{\n  \"app_name\": \"Zappo\",\n  \"personality\": \"4 Tactile / Playful LIGHT\",\n  \"personality_one_liner\": \"A vibrant, energetic, and friendly super-app that makes ordering food and hailing rides feel fast, rewarding, and distinctly Brazilian.\",\n  \"color\": {\n    \"surface\": \"#FAFAFA\",\n    \"onSurface\": \"#1A1A1A\",\n    \"surfaceSecondary\": \"#FFFFFF\",\n    \"onSurfaceSecondary\": \"#1A1A1A\",\n    \"surfaceTertiary\": \"#F4F4F5\",\n    \"onSurfaceTertiary\": \"#52525B\",\n    \"surfaceInverse\": \"#1A1A1A\",\n    \"onSurfaceInverse\": \"#FFFFFF\",\n    \"brand\": \"#FF5A26\",\n    \"onBrand\": \"#FFFFFF\",\n    \"brandPrimary\": \"#FF5A26\",\n    \"onBrandPrimary\": \"#FFFFFF\",\n    \"brandSecondary\": \"#FF8A66\",\n    \"onBrandSecondary\": \"#1A1A1A\",\n    \"brandTertiary\": \"#FFE5DD\",\n    \"onBrandTertiary\": \"#FF5A26\",\n    \"success\": \"#10B981\",\n    \"onSuccess\": \"#FFFFFF\",\n    \"warning\": \"#F59E0B\",\n    \"onWarning\": \"#FFFFFF\",\n    \"error\": \"#EF4444\",\n    \"onError\": \"#FFFFFF\",\n    \"info\": \"#52525B\",\n    \"onInfo\": \"#FFFFFF\",\n    \"border\": \"#E4E4E7\",\n    \"borderStrong\": \"#D4D4D8\",\n    \"divider\": \"#F4F4F5\",\n    \"muted\": \"#71717A\"\n  },\n  \"typography\": {\n    \"displayFontFamily\": \"Plus Jakarta Sans\",\n    \"textFontFamily\": \"Plus Jakarta Sans\",\n    \"scale\": {\n      \"sm\": 12,\n      \"base\": 14,\n      \"lg\": 16,\n      \"xl\": 20,\n      \"2xl\": 24\n    }\n  },\n  \"spacing\": {\n    \"rule\": \"Generous tactile padding. Components should feel touchable and separated by clear whitespace, not cramped.\",\n    \"xs\": 4,\n    \"sm\": 8,\n    \"md\": 12,\n    \"lg\": 16,\n    \"xl\": 24,\n    \"2xl\": 32,\n    \"3xl\": 48\n  },\n  \"radius_tokens\": {\n    \"sm\": 6,\n    \"md\": 12,\n    \"lg\": 20,\n    \"pill\": 999\n  },\n  \"shadow_tier\": \"2\",\n  \"navigation\": \"bottom_tabs\",\n  \"icon_set\": \"Phosphor\",\n  \"glassmorphism\": {\n    \"enabled\": \"true\",\n    \"do's\": [\n      \"Apply to sticky headers containing the Mobilidade/Delivery segmented control.\",\n      \"Apply to the bottom tab bar.\",\n      \"Apply to bottom-sheet drag handles and modal scrims.\",\n      \"Apply to the Driver's incoming offer radar bottom sheet.\"\n    ],\n    \"dont's\": [\n      \"Do not use on regular list items or standard cards.\",\n      \"Do not use on form inputs or body content.\"\n    ]\n  },\n  \"platform_libraries\": {\n    \"glass\": {\n      \"ios\": \"expo-glass-effect\",\n      \"android\": \"expo-blur\",\n      \"low_end_android_fallback\": \"solid surfaceSecondary\"\n    },\n    \"image\": \"expo-image\",\n    \"blur\": \"expo-blur\",\n    \"bottom_sheet\": \"@gorhom/bottom-sheet\",\n    \"animation\": \"react-native-reanimated\",\n    \"gesture\": \"react-native-gesture-handler\"\n  },\n  \"screens\": [\n    {\n      \"name\": \"Onboarding\",\n      \"purpose\": \"Introduce the Super-App concept (Rides + Food + SuperPass) with vibrant full-bleed scenes.\",\n      \"states\": {\n        \"loading\": \"Centered brand spinner.\",\n        \"empty\": \"N/A\",\n        \"error\": \"N/A\"\n      },\n      \"layout\": \"3-step carousel using full-bleed imagery, vertical gradient scrim (top to bottom fade), and a sticky primary CTA at the bottom. Playful, bouncy pagination dots.\"\n    },\n    {\n      \"name\": \"Login\",\n      \"purpose\": \"Authenticate users and route them to Client or Driver experience.\",\n      \"states\": {\n        \"loading\": \"Spinner inside the 'Entrar' button.\",\n        \"empty\": \"N/A\",\n        \"error\": \"Inline red text below the offending input field.\"\n      },\n      \"layout\": \"Clean single-column form. Large logo at the top. Segmented control or large toggle to switch between 'Cliente' and 'Motorista/Entregador'. Labels above inputs. Sticky submit at bottom inside KeyboardAvoidingView.\"\n    },\n    {\n      \"name\": \"Client Home (Início)\",\n      \"purpose\": \"Unified gateway to both Mobility and Delivery services.\",\n      \"states\": {\n        \"loading\": \"Skeleton loaders for cards and map preview.\",\n        \"empty\": \"Illustration + 'Nenhum serviço disponível na sua área'.\",\n        \"error\": \"Readable message + Retry button.\"\n      },\n      \"layout\": \"Glass header containing a prominent segmented control [ 🚗 Mobilidade | 🍔 Delivery ]. If Mobilidade: large 'Para onde?' search bar, quick chips (Casa, Trabalho), interactive map preview, SuperPass promo card. If Delivery: Horizontal categories row, 'Peça de novo' horizontal scroll, vertical restaurant feed.\"\n    },\n    {\n      \"name\": \"Mobility Flow\",\n      \"purpose\": \"Search destination, choose vehicle category, and track ride.\",\n      \"states\": {\n        \"loading\": \"Skeleton rows for vehicle categories.\",\n        \"empty\": \"N/A\",\n        \"error\": \"Error message + Retry button.\"\n      },\n      \"layout\": \"Map background. Bottom sheet for vehicle selection (Zappo X, Zappo Comfort) showing ETA and prices. Include a distinct 'SuperPass' badge showing the applied discount. Once booked: tracking view with driver info card, car marker on map, and sticky contact/cancel actions.\"\n    },\n    {\n      \"name\": \"Delivery Flow\",\n      \"purpose\": \"Browse restaurant menu, manage cart, and track food.\",\n      \"states\": {\n        \"loading\": \"Skeleton blocks for menu items.\",\n        \"empty\": \"Illustration + 'Restaurante fechado'.\",\n        \"error\": \"Error message + Retry button.\"\n      },\n      \"layout\": \"Restaurant header with cover image + gradient scrim. Sticky category tabs. Menu items with image on right, text on left. Sticky 'Ver Carrinho' CTA at the bottom. Tracking screen: vertical progress timeline and map view of courier.\"\n    },\n    {\n      \"name\": \"SuperPass\",\n      \"purpose\": \"Gamified subscription dashboard showing benefits and progress.\",\n      \"states\": {\n        \"loading\": \"Centered spinner.\",\n        \"empty\": \"N/A\",\n        \"error\": \"Error message + Retry button.\"\n      },\n      \"layout\": \"Playful layout with a large 3D reward illustration at the top. A prominent, chunky progress bar ('Faltam 2 pedidos para Frete Grátis'). Cards detailing fixed ride discounts and accumulated savings. Use success (lime) and brand (tangerine) colors to create excitement.\"\n    },\n    {\n      \"name\": \"Carteira\",\n      \"purpose\": \"Manage digital wallet, instant refunds, and payment methods.\",\n      \"states\": {\n        \"loading\": \"Skeleton lists for transaction history.\",\n        \"empty\": \"Illustration + 'Nenhuma transação ainda'.\",\n        \"error\": \"Error message + Retry button.\"\n      },\n      \"layout\": \"Large balance card at the top with a 'Adicionar Saldo' action. Below, a toggle for Payment Methods and Transaction History. Standard list rows with icons inside brandTertiary tinted squares.\"\n    },\n    {\n      \"name\": \"Support\",\n      \"purpose\": \"AI triaged chat to resolve issues or issue instant refunds.\",\n      \"states\": {\n        \"loading\": \"Typing indicator bubbles.\",\n        \"empty\": \"Initial greeting + quick action chips.\",\n        \"error\": \"Failed to send message + Retry icon.\"\n      },\n      \"layout\": \"Chat interface. Quick action chips ('Reembolso', 'Atraso') above the input field to trigger instant AI workflows. A sticky 'Falar com humano' option available in the header.\"\n    },\n    {\n      \"name\": \"Driver Home (Rodando)\",\n      \"purpose\": \"Driver's main operational view with demand heatmap.\",\n      \"states\": {\n        \"loading\": \"Map loading spinner.\",\n        \"empty\": \"N/A\",\n        \"error\": \"Location permission error + 'Permitir' button.\"\n      },\n      \"layout\": \"Full-screen map. Overlay heatmap showing high-demand zones (red/orange). Floating status pill at the top. Sticky, oversized 'Ficar Online' pill button at the bottom.\"\n    },\n    {\n      \"name\": \"Driver Radar & Navigation\",\n      \"purpose\": \"Receive offers and navigate to pickup/dropoff.\",\n      \"states\": {\n        \"loading\": \"N/A\",\n        \"empty\": \"N/A\",\n        \"error\": \"N/A\"\n      },\n      \"layout\": \"Incoming offer pops up as a high-priority bottom sheet with pulsing animations. Shows pickup, dropoff, and estimated earnings. Giant 'Aceitar' button. Active job: Turn-by-turn navigation UI on map, swipe-to-finish slider at the bottom to prevent accidental taps.\"\n    },\n    {\n      \"name\": \"Driver Ganhos\",\n      \"purpose\": \"Track earnings, goals, and performance.\",\n      \"states\": {\n        \"loading\": \"Skeleton charts.\",\n        \"empty\": \"Illustration + 'Nenhum ganho esta semana'.\",\n        \"error\": \"Error message + Retry button.\"\n      },\n      \"layout\": \"Dashboard layout. Segmented control for Hoje/Semana. Bar charts for earnings. Grid of metric cards (Viagens, Gorjetas, Horas). Progress bar for weekly goals.\"\n    }\n  ],\n  \"images\": {\n    \"feijoada_restaurant\": {\n      \"url\": \"https://images.pexels.com/photos/34234277/pexels-photo-34234277.png?auto=compress&cs=tinysrgb&dpr=2&h=650&w=940\",\n      \"alt\": \"Authentic Brazilian feijoada served with farofa, oranges, and salad.\"\n    },\n    \"superpass_reward\": {\n      \"url\": \"https://images.unsplash.com/photo-1790548156651-8a46f6b76715?crop=entropy&cs=srgb&fm=jpg&ixid=M3w3NDk1Nzd8MHwxfHNlYXJjaHwxfHxnYW1pZmllZCUyMHJld2FyZCUyMHByb2dyZXNzJTIwM2QlMjBpbGx1c3RyYXRpb258ZW58MHx8fHwxNzk1NTQ4MDA0fDA&ixlib=rb-4.1.0&q=85\",\n      \"alt\": \"An orange medal with a gold star and red ribbons amidst falling colorful confetti\"\n    },\n    \"driver_map_bg\": {\n      \"url\": \"https://images.pexels.com/photos/12276484/pexels-photo-12276484.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=650&w=940\",\n      \"alt\": \"Driver using a smartphone GPS app for navigation while on a curvy road surrounded by nature.\"\n    }\n  },\n  \"instructions_to_main_agent\": [\n    \"Implement the '4 Tactile / Playful LIGHT' personality. Use generous padding, pill-shaped buttons, and rounded cards to make the app feel friendly and touchable.\",\n    \"CRITICAL: All copy must be in Portuguese (pt-BR) as requested by the user.\",\n    \"CRITICAL: Never use blue, indigo, or purple anywhere in the app. Use Neutral Gray (#52525B) for info/neutral states.\",\n    \"Client App Navigation: Use bottom tabs (Início, Pedidos, SuperPass, Carteira, Perfil).\",\n    \"Driver App Navigation: Use bottom tabs (Rodando, Ganhos, Perfil).\",\n    \"Client Home Architecture: Do not use separate tabs for Mobility and Delivery. Instead, use a segmented control [ 🚗 Mobilidade | 🍔 Delivery ] inside the glass header of the 'Início' tab to switch contexts instantly.\",\n    \"SuperPass Gamification: Emphasize the progress bar for free delivery unlocks. Use the 'superpass_reward' 3D illustration and vibrant success/brand colors to make it feel rewarding.\",\n    \"Driver Heatmap: The 'Rodando' screen must feature a map with a heatmap overlay indicating high-demand zones, crucial for the driver's operational efficiency.\",\n    \"Images: Always apply a vertical gradient scrim (transparent to ≥70% surfaceInverse) when placing text over images, such as on the restaurant header or onboarding screens.\"\n  ]\n}","overwrite":true,"path":"/app/design_guidelines.json"})
